// One item per line (commas work too).
const sites = String($json.websites || '').split(/\n|,/).map(s => s.trim()).filter(Boolean)
if (!sites.length) throw new Error('Add at least one website to Set Website List, one per line.')
return sites.map(website => ({ json: { website }, pairedItem: { item: 0 } }))

const sites = $('Split Into One Item per Website').all()
return $input.all().map((item, i) => {
  const b = item.json, c = b.colors || {}
  return { json: {
    website: sites[i]?.json.website || b.url,
    name: b.siteName || '',
    primary: c.primary || '', accent: c.accent || '', background: c.background || '', text: c.text || '',
    fonts: (b.fonts || []).join(', '),
    logo: b.logo || '',
    confidence: b.confidence ?? '',
    colors_from: b.signals?.primarySource || '',
    error: b.error ? String(b.error.message || b.error) : '',
  }, pairedItem: { item: i } }
})
